// 1. تحويل الإحداثيات صراحة إلى أرقام (Numbers) لتجنب كسر الـ JSON
const lat = Number($json.latitude);
const lon = Number($json.longitude);
const offset = 0.05;

// 2. دالة تقدير المنطقة الزمنية في الولايات المتحدة بناءً على خط الطول
function getTimezone(lng) {
  if (lng > -85.0) return 'America/New_York';       // Eastern Time (ET)
  if (lng > -103.0) return 'America/Chicago';      // Central Time (CT)
  if (lng > -114.0) return 'America/Denver';       // Mountain Time (MT)
  return 'America/Los_Angeles';                    // Pacific Time (PT)
}

// 3. تحديد المنطقة الزمنية وحساب الوقت والتاريخ المحلي للمزارع (مع خصم 3 ساعات لضمان توفر البيانات)
const userTimezone = getTimezone(lon);
const localTime = DateTime.now().setZone(userTimezone).minus({ hours: 3 });

// 4. إرجاع النتيجة مع حساب الإحداثيات كأرقام رياضية خالية من النص
return [{
  json: {
    latitude: lat,
    longitude: lon,
    timezone: userTimezone,
    start_date: localTime.toFormat('yyyy-MM-dd'),
    start_time: localTime.toFormat('HH:00'),
    polygon_aoi: {
      type: "FeatureCollection",
      features: [{
        type: "Feature",
        properties: {},
        geometry: {
          type: "Polygon",
          coordinates: [[
            [Number((lon - offset).toFixed(6)), Number((lat - offset).toFixed(6))],
            [Number((lon + offset).toFixed(6)), Number((lat - offset).toFixed(6))],
            [Number((lon + offset).toFixed(6)), Number((lat + offset).toFixed(6))],
            [Number((lon - offset).toFixed(6)), Number((lat + offset).toFixed(6))],
            [Number((lon - offset).toFixed(6)), Number((lat - offset).toFixed(6))]
          ]]
        }
      }]
    }
  }
}];

// 1. Get farmer data from the current loop item
const farmerData = $("Loop Over Items1").item.json;
const farmerName = farmerData.Name || "Farmer";
const userCrops = farmerData.crops || "";

// 2. Extract Data from original source & Dynamic Timezone from HTTP Request
const responseData = $input.item.json;

// قراءة درجة الحرارة من مصدرك الأصلي المعتمد (وليس من weather API الجديد)
let tempC = responseData.average_temperature ?? responseData.temperature ?? responseData.temp;

if (tempC === undefined || tempC === null) {
  const dataRoot = responseData.body || responseData.data || responseData;
  tempC = dataRoot.average_temperature ?? dataRoot.temperature ?? dataRoot.temp ?? 25;
}

tempC = Number(Number(tempC).toFixed(1));
const tempF = (tempC * 9/5 + 32).toFixed(1);

// استخراج المنطقة الزمنية فقط من عقدة الـ HTTP Request (مثل America/Los_Angeles)
const userTimeZone = responseData.timezone || farmerData.timezone || 'America/Chicago';

// حساب الوقت والتاريخ المحلي الخاصين بموقع المزارع الجغرافي
const now = new Date();
const optionsDate = { timeZone: userTimeZone, year: 'numeric', month: '2-digit', day: '2-digit' };
const optionsTime = { timeZone: userTimeZone, hour: '2-digit', minute: '2-digit', hour12: true };

const reportDate = new Intl.DateTimeFormat('en-CA', optionsDate).format(now); // YYYY-MM-DD
const reportTime = new Intl.DateTimeFormat('en-US', optionsTime).format(now); // hh:mm AM/PM

// 3. Process Temperature History (Maintains a rolling 7-day history window)
let history = [];
try {
  history = farmerData.temperature_history ? JSON.parse(farmerData.temperature_history) : [];
} catch (e) {
  history = [];
}
history.push(tempC);
if (history.length > 7) history.shift();

const n = history.length;
const meanTempC = (history.reduce((a, b) => a + b, 0) / n);
const meanTempF = (meanTempC * 9/5 + 32).toFixed(1);

const variance = history.reduce((sum, val) => sum + Math.pow(val - meanTempC, 2), 0) / (n || 1);
const stdDev = Math.sqrt(variance);
const zScoreNum = stdDev > 0 ? ((tempC - meanTempC) / stdDev) : 0;
const zScoreDisplay = zScoreNum.toFixed(2);
const heatSpikeAlert = zScoreNum > 1.5 ? "Sudden Heat Spike Detected" : "Normal Variation";

let trend = "Stable";
if (tempC > meanTempC + 1.5) trend = "Sharply Rising";
else if (tempC > meanTempC) trend = "Slightly Increasing";
else if (tempC < meanTempC - 1.5) trend = "Cooling Down";

// ---- Normal CDF helpers ----
function erf(x) {
  const sign = x < 0 ? -1 : 1;
  x = Math.abs(x);
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741,
        a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const t = 1 / (1 + p * x);
  const y = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return sign * y;
}
function normalCDF(z) { return 0.5 * (1 + erf(z / Math.sqrt(2))); }
function computeRiskProbability(thresholdC, meanTempC, stdDev) {
  const safeStdDev = stdDev > 0.1 ? stdDev : 0.5;
  const z = (thresholdC - meanTempC) / safeStdDev;
  const prob = Math.round((1 - normalCDF(z)) * 100);
  return Math.max(1, Math.min(prob, 99));
}

// 4. Scientific Thresholds
const benchmarks = {
  "corn": { stressC: 30, stressF: 86, impact: "pollen viability loss", action: "Run pre-cooling irrigation before 8:00 AM." },
  "tomatoes": { stressC: 29, stressF: 85, impact: "blossom drop and sunscald", action: "Deploy 30% shade netting and mulch the soil." },
  "soybeans": { stressC: 32, stressF: 90, impact: "pod abortion", action: "Apply surface irrigation, avoid peak-hour fertilizing." },
  "lettuce": { stressC: 24, stressF: 75, impact: "early bolting", action: "Activate overhead misting." },
  "strawberries": { stressC: 26, stressF: 78, impact: "fruit softening", action: "Run drip irrigation and root-zone cooling." },
  "dairy cows": { stressC: 25, stressF: 77, impact: "milk yield drop", action: "Turn on barn misting/fans, add shade and cool water." },
  "beef cattle": { stressC: 28, stressF: 82, impact: "reduced feed intake", action: "Feed early morning/evening, provide shaded area." }
};

// 5. Analyze each crop/livestock item
let statsPerItem = [];
let maxProbability = 0;
let totalCumulativeHeat = 0;

const parsedItems = userCrops.split(/,|and|\+/).map(i => i.trim().toLowerCase()).filter(Boolean);

parsedItems.forEach(itemKey => {
  const matchedKey = Object.keys(benchmarks).find(b => itemKey.includes(b));
  const displayName = itemKey.charAt(0).toUpperCase() + itemKey.slice(1);
  const rule = matchedKey ? benchmarks[matchedKey] : { stressC: 28, stressF: 82, impact: "general heat stress", action: "Ensure irrigation or shade." };

  let cumulativeHeat = 0;
  history.forEach(t => { if (t > rule.stressC) cumulativeHeat += (t - rule.stressC); });
  if (cumulativeHeat > totalCumulativeHeat) totalCumulativeHeat = cumulativeHeat;

  const prob = computeRiskProbability(rule.stressC, meanTempC, stdDev);
  if (prob > maxProbability) maxProbability = prob;

  const isStressed = tempC >= rule.stressC;

  let level = "green";
  if (isStressed || prob >= 66) level = "red";
  else if (prob >= 31) level = "yellow";

  statsPerItem.push({
    name: displayName,
    type: matchedKey || "general",
    thresholdC: rule.stressC,
    thresholdF: rule.stressF,
    isStressed,
    riskProbability: prob,
    level,
    impact: rule.impact,
    action: rule.action,
    cumulativeHeat: Number(cumulativeHeat.toFixed(1))
  });
});

// Sort by severity: red first, then yellow, then green
const levelOrder = { red: 0, yellow: 1, green: 2 };
statsPerItem.sort((a, b) => levelOrder[a.level] - levelOrder[b.level]);

// 6. Build SIMPLE farmer-facing message
const emojiFor = { red: "🔴", yellow: "🟡", green: "🟢" };
const lines = statsPerItem.map(item => {
  const emoji = emojiFor[item.level];
  if (item.level === "red") {
    return `${emoji} ${item.name}: Heat Risk — ${item.action}`;
  } else if (item.level === "yellow") {
    return `${emoji} ${item.name}: Monitor — ${item.riskProbability}% heat stress risk within 48h`;
  } else {
    return `${emoji} ${item.name}: Safe — No immediate action required`;
  }
});

const simpleMessage = `🌾 Daily Thermal Bulletin for ${farmerName}
📅 Date: ${reportDate} | Time: ${reportTime}
🌡️ Current Temp: ${tempC}°C (${tempF}°F)

${lines.join("\n")}

📊 For detailed analytics & historical trends, check your dashboard.`;

// 7. Build DETAILED statistical payload (For Google Sheet / Dashboard Webpage)
const dashboardPayload = {
  farmerId: farmerData.Id,
  farmerName: farmerName,
  timestamp: now.toISOString(),
  localDate: reportDate,
  localTime: reportTime,
  timezone: userTimeZone,
  currentTempC: tempC,
  currentTempF: Number(tempF),
  temperatureHistory: history,
  movingAverageC: Number(meanTempC.toFixed(1)),
  movingAverageF: Number(meanTempF),
  trend: trend,
  zScore: Number(zScoreDisplay),
  heatAnomalyStatus: heatSpikeAlert,
  cumulativeThermalStress: Number(totalCumulativeHeat.toFixed(1)),
  maxRiskProbability: maxProbability,
  items: statsPerItem
};

return {
  json: {
    chat_id: farmerData.Id,
    updated_history: JSON.stringify(history),
    message: simpleMessage,
    dashboard_data: JSON.stringify(dashboardPayload)
  }
};
